    /// Reads the changes of the object: the base class first, then the
    /// changed-fields mask and the changed members of this class.
    pub fn deserialize_changes_core(
        &self,
        host: &dyn ServerCompositionTargetHooks,
        reader: &mut BatchStreamReader<'_>,
        _committed_at: Duration,
    ) {
        let compositor = host.server_compositor();
        ServerCompositionTargetHooks::deserialize_changes_extra(host, reader);
        let changed = reader.read::<CompositionTargetChangedFields>();
        if changed.contains(CompositionTargetChangedFields::ROOT) {
            let value = read_server_object(reader, compositor.as_ref());
            self.set_root(host, value);
        }
        if changed.contains(CompositionTargetChangedFields::IS_ENABLED) {
            let value = reader.read::<bool>();
            self.set_is_enabled(host, value);
        }
        if changed.contains(CompositionTargetChangedFields::DEBUG_OVERLAYS) {
            let value = reader.read::<RendererDebugOverlays>();
            self.set_debug_overlays(host, value);
        }
        if changed.contains(CompositionTargetChangedFields::LAST_LAYOUT_PASS_TIMING) {
            let value = reader.read::<LayoutPassTiming>();
            self.set_last_layout_pass_timing(host, value);
        }
        if changed.contains(CompositionTargetChangedFields::SCALING) {
            let value = reader.read::<f64>();
            self.set_scaling(host, value);
        }
        if changed.contains(CompositionTargetChangedFields::SIZE) {
            let value = reader.read::<Size>();
            self.set_size(host, value);
        }
        if changed.contains(CompositionTargetChangedFields::TRANSPARENCY_LEVEL) {
            let value = reader.read::<CompositionTransparencyLevel>();
            self.set_transparency_level(host, value);
        }
        if changed.contains(CompositionTargetChangedFields::PLATFORM_SPECIFIC_SCENE_INFO) {
            let value = reader.read_value::<Rc<dyn Any>>();
            self.set_platform_specific_scene_info(host, value);
        }
        ServerCompositionTargetHooks::on_fields_deserialized(host, changed);
    }

    /// The composition property with the given name, among the properties
